if (context.element.id === 'source_pick') {
  const v = String(context.element.value ?? '').trim();
  context.grafana.locationService.partial({'var-edit_source_key': v}, true);
  const syncObj = {};
  syncObj['source_pick'] = v;
  context.panel.setFormValue(syncObj);
  if (!v) {
    context.panel.setFormValue({ point_id: '', metric: '', device_id: '' });
  }
  const focusPrimaryField = () => {
    if (typeof document === 'undefined') return;
    const selectors = [
      'input[name="source_key"]',
      'textarea[name="source_key"]',
      'input[id="source_key"]',
      '[aria-label="source_key"]',
      '[data-testid*="source_key"] input',
    ];
    for (const selector of selectors) {
      const el = document.querySelector(selector);
      if (el && typeof el.focus === 'function') {
        el.focus();
        if (typeof el.select === 'function') {
          el.select();
        }
        break;
      }
    }
  };
  setTimeout(focusPrimaryField, 0);
  setTimeout(focusPrimaryField, 120);
}

